  // src/utils.ts
  function escapeHtml(value) {
    return String(value ?? "").replace(/[&<>'"]/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", "'": "&#39;", '"': "&quot;" })[char]);
  }
  var NAME_OVERRIDES = {
    ThunderCelestialShroomPlant: "Stormcap",
    ThunderCelestial: "Thunderpeel"
  };
  function humanize(value) {
    const id = String(value || "");
    return NAME_OVERRIDES[id] ?? id.replace(/_NEW$/, "").replace(/([a-z0-9])([A-Z])/g, "$1 $2").replace(/([A-Za-z])([IVX]+)$/g, "$1 $2");
  }
  function formatDuration(ms) {
    const total = Math.max(0, Math.ceil(ms / 1e3));
    const hours = Math.floor(total / 3600);
    const minutes = Math.floor(total % 3600 / 60);
    const seconds = total % 60;
    return hours ? `${hours}h ${String(minutes).padStart(2, "0")}m` : `${minutes}m ${String(seconds).padStart(2, "0")}s`;
  }
  function loadLocal(key, fallback) {
    try {
      return JSON.parse(localStorage.getItem(key) || "null") ?? fallback;
    } catch {
      return fallback;
    }
  }
  function saveLocal(key, value) {
    try {
      localStorage.setItem(key, JSON.stringify(value));
    } catch {
    }
  }
  function saveLocalOrFail(key, value) {
    try {
      localStorage.setItem(key, JSON.stringify(value));
      return true;
    } catch {
      return false;
    }
  }

